import{c as t,Q as a,j as o,m as i}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"/via-negativa: a useful skill to invert and simplify your product","description":"","frontmatter":{"url":"https://x.com/nurijanian/status/2078456110944845969","title":"/via-negativa: a useful skill to invert and simplify your product","author":"nurijanian","archived":"2026-07-30T00:00:00.000Z","handle":"@nurijanian","published":"2026-07-18T00:00:00.000Z","stats":"57 likes · 3 retweets · 120 bookmarks · 20851 views","tags":["via-negativa","subtraction","taleb","product-management","ai-pm-os"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-18-@nurijanian-845969.md","filePath":"research/tweets/2026-07-18-@nurijanian-845969.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-07-18-@nurijanian-845969.md"};function s(n,e,l,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="via-negativa-a-useful-skill-to-invert-and-simplify-your-product-—-nurijanian" tabindex="-1">/via-negativa: a useful skill to invert and simplify your product — @nurijanian <a class="header-anchor" href="#via-negativa-a-useful-skill-to-invert-and-simplify-your-product-—-nurijanian" aria-label="Permalink to &quot;/via-negativa: a useful skill to invert and simplify your product — @nurijanian&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/nurijanian/status/2078456110944845969" target="_blank" rel="noreferrer">https://x.com/nurijanian/status/2078456110944845969</a><strong>作者</strong>：nurijanian（@nurijanian） <strong>發布日期</strong>：2026-07-18 <strong>收錄日期</strong>：2026-07-30 <strong>類型</strong>：Twitter Article <strong>統計</strong>：57 likes · 3 retweets · 120 bookmarks · 20851 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>When I think about the best people I&#39;ve worked with, they always simplify the product or the business. They do not complicate it. You simplify mostly by removing.</p><p>It is hard to simplify in a culture of build, build, build. Most of the time the job is adding stuff, never removing.</p><p>Just removing stuff is not the answer either. The approach that works is removing to grow: cut against one purpose, so the thing gets simpler without getting weaker.</p><h2 id="why-cutting-beats-adding" tabindex="-1">Why cutting beats adding <a class="header-anchor" href="#why-cutting-beats-adding" aria-label="Permalink to &quot;Why cutting beats adding&quot;">​</a></h2><p>Nassim Taleb has a name for this in Antifragile. He calls it via negativa. It is a recipe for what to avoid, what not to do, cutting rather than adding.</p><p>His deeper point is about how sure we can be.</p><p>We are far more sure about what is wrong than about what is right. What we think is right today can turn out wrong tomorrow, but what we already know to be broken rarely turns out fine. The new needs to earn it&#39;s keep, but the old, if it remains, already has - so keeping it is wise.</p><h2 id="the-method-purpose-locked-subtraction" tabindex="-1">The method: purpose-locked subtraction <a class="header-anchor" href="#the-method-purpose-locked-subtraction" aria-label="Permalink to &quot;The method: purpose-locked subtraction&quot;">​</a></h2><ol><li>Start with the purpose. Write one sentence naming the single job this product, doc, offer, or flow exists to do. One job, not three.</li><li>Then list every piece of the thing: every feature, every section, every field, every step. It is boring, slow, and the step most people skip under pressure.</li><li>Now tag each piece against the purpose sentence. Keep it if it earns its place. Cut it if it does not. &quot;Nice to have&quot; counts as a cut. That single rule does most of the work.</li></ol><p>The hard tags are the risky-cuts: the pieces you suspect are dead weight but are not sure about. Those do not get a &quot;maybe.&quot; Each risky-cut gets a stated downside and a yes or no. If you cannot name the failure that follows when it goes, that tells you something too.</p><h2 id="why-this-is-hard" tabindex="-1">Why this is hard <a class="header-anchor" href="#why-this-is-hard" aria-label="Permalink to &quot;Why this is hard&quot;">​</a></h2><p>The boredom is not the real problem. The hard part is the judgment.</p><p>Without a purpose sentence, every cut becomes taste or politics. You argue about which pieces &quot;count,&quot; and the loudest person, or the person whose feature it is, usually wins. Cutting someone&#39;s pet feature feels like saying no to them. The purpose gate lets you say no to the piece instead of no to the person.</p><p>And the clear pushback: teams already run cleanups and kill lists. That is true. But a cleanup without a one-sentence purpose argues for years about which pieces belong. The method adds two things a kill list usually lacks: the test for fit, and the forced keep-or-remove on the risky ones. Adding can still happen. The claim is tighter: when bloat is the problem, lasting gains come from cutting against purpose first.</p><h2 id="now-do-it-ten-times-a-day" tabindex="-1">Now do it ten times a day <a class="header-anchor" href="#now-do-it-ten-times-a-day" aria-label="Permalink to &quot;Now do it ten times a day&quot;">​</a></h2><p>By hand on one doc, the method works. Most of the keep and cut calls are in your head already. You are short on scale, not judgment.</p><p>Now it is not one doc. Agents draft flows, feature proposals, specs, and pages faster than you can read them. The pile of things that need a purpose check climbs every week. You cannot hold ten purpose sentences and ten lists in your head in the moment. A blank template does not get easier to fill out when ten of them are waiting.</p><h2 id="so-give-your-agent-this-skill" tabindex="-1">So give your agent this skill <a class="header-anchor" href="#so-give-your-agent-this-skill" aria-label="Permalink to &quot;So give your agent this skill&quot;">​</a></h2><p>[圖 1]</p><p><code>via-negativa</code> is one of the 240+ skills inside PM OS, the Product Manager&#39;s AI Operating System. It&#39;s updated at least once every 2 weeks, and is on version 2.5.</p><p>It runs in Claude Code, Cowork or Cursor on top of your company context files, so the purpose-locked cut lists and stripped versions come back grounded in your product, your users, and your real constraints, instead of generic PM advice that could have come from any blog post.</p><p>You don&#39;t have to assemble any of it. PM OS wires <code>via-negativa</code> into the broader operating layer alongside workflows for strategy, research, decisions, stakeholder work, and measurement.</p><h2 id="if-you-want-the-full-os-it-s-here" tabindex="-1">If you want the full OS, it&#39;s here. <a class="header-anchor" href="#if-you-want-the-full-os-it-s-here" aria-label="Permalink to &quot;If you want the full OS, it&#39;s here.&quot;">​</a></h2><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Taleb 的 via negativa（減法優於加法）包裝成「purpose-locked subtraction」方法——一句話定義目的→列出所有元件→逐項標記保留/刪除，風險刪項強制寫明具體後果，不留「maybe」。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>減法優於加法的認識論理由</strong>：我們對「什麼是錯的」比對「什麼是對的」更有把握；舊元件已證明能撐住，新元件還沒獲得信任</li><li><strong>Purpose-locked subtraction 三步驟</strong>：① 寫一句話目的（單一任務，非三個）② 列出所有元件 ③ 逐項對照目的標記保留/刪除，「nice to have」直接算刪除</li><li><strong>風險刪項強制二選一</strong>：不確定是否為冗餘的元件，必須寫出「若刪除會發生的具體後果」再做是否保留的決定，「說不出後果」本身就是訊號</li><li><strong>目的句避免政治化決策</strong>：沒有目的句時，刪減會淪為品味或政治角力（誰的功能就留誰的），目的句讓否決對象是「元件」而非「人」</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>無實驗數據，方法論為作者個人觀察</li><li>提及產品：PM OS（240+ skills，跑在 Claude Code/Cowork/Cursor，版本 2.5，同作者前一篇 <code>mckinsey-issue-tree</code> 同一產品系列）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>全文為同一作者（@nurijanian）前一篇 <code>mckinsey-issue-tree</code> 文章的同系列業配文，套用相同「方法論 + PM OS 產品推廣」結構</li><li>「purpose-locked subtraction」與本 workspace <code>core.md §PROPOSE</code>「最小變更 / Rule of 3」精神方向一致，但本文提供的是通用產品管理框架，非可直接複製的 prompt 或腳本</li><li>方法論本身可作為本 workspace 既有 <code>skill-roster-audit</code>（skill/agent roster 常駐稅稽核）的補充視角——用「一句話目的」逐項檢驗 skill 是否該保留，但需自行改寫才能落地，本文未提供 workspace 相關的具體操作化</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>5/10</td><td>方法論方向與既有 skill-roster-audit 精神相符，但無現成可套用的 prompt/流程</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>Via negativa 概念沿用 Taleb，「purpose-locked subtraction + 風險刪項強制表態」的具體化有一定價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>3/10</td><td>純個人觀察與產品推廣，無數據佐證</td></tr><tr><td>D. 技術深度 (15%)</td><td>2/10</td><td>無實際 prompt 或 config，純概念層級</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>減法方法論適用任何系統精簡場景，跨領域通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>4.3/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：方法論方向與既有 skill-roster-audit 精神相符但無可直接落地細節，且為同系列產品業配文，僅存檔備查。</p>',40)])])}const g=t(r,[["render",s]]);export{c as __pageData,g as default};
